SELECT psp.account_id, psp.code, psp.is_active AS active
  FROM merchant_psp enabled
  JOIN account psp ON psp.account_id = enabled.psp_account_id
 WHERE enabled.account_id = #{merchantAccountId}
   AND psp.code = #{pspCode}
   AND psp.account_type_id = 4

SELECT EXISTS (
  SELECT 1
    FROM merchant_fee_configuration
   WHERE account_id = #{merchantAccountId}
     AND currency_id = #{currencyId}
)

