mapper.update:
UPDATE merchant_order
   SET phase_claim_token = #{claimToken}
 WHERE order_id = #{orderId}
   AND order_phase = #{phase}

UPDATE merchant_order
   SET phase_claim_token = NULL
 WHERE order_id = #{orderId}
   AND order_phase = #{phase}
   AND phase_claim_token = #{claimToken}

UPDATE merchant_order
   SET order_phase = 'LEDGER_CREATED',
       phase_claim_token = NULL
 WHERE order_id = #{orderId}
   AND order_phase = 'ORDER_PERSISTED'
   AND phase_claim_token = #{claimToken}

UPDATE order_payment
   SET psp_reference = #{pspReference}, payment_link = #{paymentLink}
 WHERE order_id = #{orderId}
   AND EXISTS (
     SELECT 1
       FROM merchant_order
      WHERE order_id = #{orderId}
        AND order_phase = 'LEDGER_CREATED'
        AND phase_claim_token = #{claimToken}
   )
   AND (psp_reference IS NULL OR psp_reference = #{pspReference})
   AND (payment_link IS NULL OR payment_link = #{paymentLink})

UPDATE merchant_order
   SET order_phase = 'PSP_CREATED',
       phase_claim_token = NULL
 WHERE order_id = #{orderId}
   AND order_phase = 'LEDGER_CREATED'
   AND phase_claim_token = #{claimToken}

UPDATE merchant_order
   SET order_phase = 'COMPLETED',
       phase_claim_token = NULL
 WHERE order_id = #{orderId}
   AND order_phase = 'PSP_CREATED'
   AND phase_claim_token = #{claimToken}
